}

.box::after {
  /**
  * Пробел нулевой ширины
  * Для выравнивания относительно текста
  */
  content: '\200b';
}

/** иконка галочки скрыта, пока нет класса checked (в indeterminate показывается минус) */
.root:not(.indeterminate) .box svg {
  visibility: hidden;
}

/** focus — снимаем UA-outline с фокусируемого .root, кольцо только на .box */
.root:focus-visible {
  outline: none;
}

.root:focus-visible .box {
  outline: 2px solid var(--stroke-control-focused);
  outline-offset: 2px;
}

/** hover */
.root:not(.disabled):not(.invalid):hover .box {
  background: var(--surface-inverted-default);
  border-color: var(--stroke-control-hovered);
}

/** active */
.root:not(.disabled):not(.invalid):active .box {
  background: var(--surface-inverted-pressed);
  border-color: var(--stroke-control-pressed);
}

/** checked */
.root.checked .box,
.root.indeterminate .box {
  background: var(--control-main-primary-default);
  border-color: var(--control-main-primary-default);
}

.root.checked .box svg {
  visibility: visible;
}

/** checked hover */
.root.checked:not(.disabled):hover .box,
.root.indeterminate:not(.disabled):hover .box {
  background: var(--control-main-primary-hovered);
  border-color: var(--control-main-primary-hovered);
}

/** checked active */
.root.checked:not(.disabled):active .box,
.root.indeterminate:not(.disabled):active .box {
  background: var(--control-main-primary-pressed);
  border-color: var(--control-main-primary-pressed);
}

/** invalid */
.root.invalid .box {
  background: var(--surface-negative-default);
  border-color: var(--stroke-border-negative);
}

/** invalid hover */
.root.invalid:not(.disabled):not(.checked):not(.indeterminate):hover .box {
  background: var(--surface-negative-hovered);
  border-color: var(--stroke-border-negative);
}

/** invalid active */
.root.invalid:not(.disabled):not(.checked):not(.indeterminate):active .box {
  background: var(--surface-negative-pressed);
  border-color: var(--stroke-border-negative);
}

/** checked invalid */
.root.invalid.checked .box,
.root.invalid.indeterminate .box {
  background: var(--control-negative-primary-default);
  border-color: var(--control-negative-primary-default);
}

/** checked invalid hover */
.root.invalid.checked:not(.disabled):hover .box,
.root.invalid.indeterminate:not(.disabled):hover .box {
  background: var(--control-negative-primary-hovered);
  border-color: var(--control-negative-primary-hovered);
}

/** checked invalid active */
.root.invalid.checked:not(.disabled):active .box,
.root.invalid.indeterminate:not(.disabled):active .box {
  background: var(--control-negative-primary-pressed);
  border-color: var(--control-negative-primary-pressed);
}

/** all disabled (important потому что отключенный чекбокс имеет наивысший приоритет) */
.root.disabled .box {
  background: var(--surface-inverted-disabled) !important;
  border-color: var(--stroke-control-default) !important;
}

.root.disabled.checked .box,
.root.disabled.indeterminate .box {
  background: var(--surface-inverted-disabled) !important;
  border-color: var(--surface-inverted-disabled) !important;
}

.root.disabled.checked .box svg {
  visibility: visible;
}

