/*
 * Глобальные ресурсы синхронизации шиммера.
 *
 * Через `--shimmer-progress` (число 0..1) вложенные `Skeleton` читают одну фазу волны
 * от ближайшего предка, на котором запущена анимация. Это даёт три слоя sync без
 * React-context:
 *
 * - Standalone `<Skeleton />`: анимация на самом `.skeleton` → шейп тикает свой прогресс.
 * - `<SkeletonGroup>` (default `scope="group"`): анимация на `[data-skeleton-group]` →
 *   все вложенные `.skeleton` имеют общий прогресс → волна непрерывна внутри группы.
 * - `<SkeletonGroup scope="page">` (opt-in): JS вешает `data-cian-skeleton-page-sync` на
 *   `<body>`, и эта группа отказывается от собственной анимации, наследуя
 *   прогресс с body. Так несколько `scope="page"`-групп остаются синхронны между собой
 *   и переживают streaming SSR.
 *
 */
@property --shimmer-progress {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

@keyframes cian-skeleton-progress {
  0% {
    --shimmer-progress: 0;
  }

  70%,
  100% {
    --shimmer-progress: 1;
  }
}

.skeleton {
  position: relative;
  display: block;
  overflow: hidden;
  width: 100%;
  height: var(--unit_4);
  background-color: var(--surface-neutral-disabled);
  border-radius: var(--unit_1);
  animation: cian-skeleton-progress 2000ms ease-out 500ms infinite;
}

.skeleton.inline {
  display: inline-block;
}

/*
 * SkeletonGroup — query container для шейпов внутри. `100cqw` в `::after` шейпов отдаёт
 * ширину группы, и работает мгновенно — не ждёт
 * `useLayoutEffect`. Так групповая волна получает правильную «ширину» сразу
 *
 * Тут же запускается анимация прогресса: шейпы с `animation: none` (см. ниже) наследуют
 * фазу с группы.
 */
:global([data-skeleton-group]) {
  container-type: inline-size;
  animation: cian-skeleton-progress 2000ms ease-out 500ms infinite;
}

:global([data-skeleton-group]) .skeleton {
  animation: none;
}

/*
 * Page-scope режим. JS-refcount в `SkeletonGroup` ставит `data-cian-skeleton-page-sync`
 * на `<body>`, и группа отказывается от собственного тика. `--shimmer-progress`
 * наследуется с body → группы с `scope="page"` синхронны между собой.
 *
 */
:global([data-skeleton-group][data-skeleton-scope='page']) {
  animation: none;
}

:global(body[data-cian-skeleton-page-sync]) {
  animation: cian-skeleton-progress 2000ms ease-out 500ms infinite;
}

/*
 * Шиммер: highlight в центре — `--surface-inverted-default`, края — прозрачные.
 *
 * Inline, а не `var(--skeleton-primary)`: значение токена живёт на `:root`, и
 * вложенные `var()` ссылки на surface-* зашиваются в light-палитру. Чтобы шиммер
 * подхватывал тему страницы (dark / colored / onOverlay), повторяем содержимое
 * инлайн — `var()` внутри `background-image` пересчитывается в скоупе `.skeleton::after`.
 *
 * Края — `transparent`. В opaque-темах визуально неотличимо от `--surface-neutral-disabled`
 * (тот же цвет, что и подложка). В alpha-темах (colored / onOverlay) непрозрачные края
 * градиента стекались бы по альфе с такой же полупрозрачной подложкой и давали бы видимый
 * прямоугольник по контуру волны — `transparent` убирает этот стык.
 *
 */
.skeleton::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(270deg, transparent 0%, transparent 20%, var(--surface-inverted-default) 50%, transparent 80%, transparent 100%);
  background-repeat: no-repeat;
  background-size: 200% 100%;
  background-position-x: calc(200% - 300% * var(--shimmer-progress, 0));
  pointer-events: none;
}

/*
 * Шейпы внутри `SkeletonGroup` всегда используют групповую формулу — никакого ожидания
 * JS. `100cqw` через `container-type: inline-size` на самой группе раскрывается в её
 * ширину, поэтому волна сразу имеет «правильный» размер — длиной во всю группу.
 *
 * `--shimmer-offset-x` — смещение шейпа от левого края группы. Источники значения:
 *   1. Inline-style на ячейке `template`: `calc(<col> * 100cqw / <cols>)` — попадает в
 *      DOM при первом рендере, без JS. Сразу даёт точную фазу для grid-раскладок.
 *   2. ResizeObserver в `SkeletonGroup` после mount-а: ставит точное пиксельное значение
 *      для freeform-раскладок (горизонтальный flex с произвольными ширинами). До замера
 *      offset = 0 (фоллбэк), волны фриформа идут «фантомами» до гидрации; пост-гидрации
 *      JS перетирает на точные значения.
 *
 */
:global([data-skeleton-group] [data-skeleton-shape])::after {
  background-size: 100cqw 100%;
  background-position-x: calc(
    -100cqw + 2 * 100cqw * var(--shimmer-progress, 0) - var(--shimmer-offset-x, 0px)
  );
}

@media (prefers-reduced-motion: reduce) {
  .skeleton,
  :global([data-skeleton-group]),
  :global(body[data-cian-skeleton-page-sync]) {
    animation: none;
  }

  .skeleton::after {
    opacity: 0;
  }
}

