/* START Dialog Overlay */
.overlay {
  position: fixed;
  inset: 0;
  z-index: var(--zIndex_modal);
  will-change: opacity;
}

.overlay::before {
  position: fixed;
  content: '';
  inset: 0;
  background-color: var(--overlay-default);
  transition: background var(--transition-option);
}

.overlay-transparent::before {
  background-color: var(--transparent-black0a);
}

.overlay-blured::before {
  backdrop-filter: blur(var(--unit_2));
}
/* END Dialog Overlay */

/* START Dialog Close */
.close {
  position: absolute;
  z-index: 2;
  top: 0;
  right: 0;
  width: 100%;
}

.close-sticky {
  position: sticky;
}

.close-inner {
  position: absolute;
  top: var(--unit_3);
  right: var(--unit_3);
}
/* END Dialog Close */

/* START Dialog Content */
.content-wrapper {
  position: absolute;
  display: flex;
  overflow: auto;
  overscroll-behavior: none;
  inset: 0;
}

.content-wrapper-animating {
  overflow: hidden;
}

.content-inner {
  margin: auto;
  padding: var(--unit_8) 0;
  flex-grow: 1;
}

.content {
  position: relative;
  z-index: 1;
  margin: auto;
  box-sizing: border-box;
  max-width: 100%;
  min-height: auto;
  background-color: var(--background-primary);
  border-radius: var(--unit_4);
  border-top: 1px solid var(--stroke-border-neutral);
  outline: none;
  box-shadow: 0 8px 16px 0 var(--shadow-default);
  will-change: transform;
}

.swipe-handle {
  position: absolute;
  top: calc(-1 * var(--unit_4));
  left: 0;
  right: 0;
  height: var(--unit_8);
  user-select: none;
  touch-action: none;
  z-index: 2;
  cursor: grab;
}

.content-l {
  width: 880px;
}

.content-m {
  width: 640px;
}

.content-s {
  width: 480px;
}

@media (max-width: 880px) {
  .content-l {
    width: 640px;
  }

  .content-m {
    width: 480px;
  }
}

@media (max-width: 640px) {
  .content-inner {
    margin: auto auto 0;
    padding-bottom: 0;
  }

  .content {
    width: 100%;
    border-radius: var(--unit_4) var(--unit_4) 0 0;
  }
}
/* END Dialog Content */

/* START Dialog Header */
.header {
  padding: var(--unit_7) var(--unit_8) var(--unit_5);
  display: flex;
  flex-direction: column;
  background: var(--background-primary);
  border-radius: var(--unit_4) var(--unit_4) 0 0;
}

.header-sticky {
  position: sticky;
  top: 0;
  z-index: inherit;
}

.header + .body {
  padding-top: 0;
}

@media (max-width: 640px) {
  .header {
    padding: var(--unit_5) var(--unit_8) var(--unit_4) var(--unit_4);
  }
}
/* END Dialog Header */

/* START Dialog Body */
.body {
  padding: 0 var(--unit_8);
}

@media (max-width: 640px) {
  .body {
    padding: 0 var(--unit_4);
  }
}
/* END Dialog Body */

/* START Dialog Footer */
.footer {
  bottom: 0;
  padding: var(--unit_5) var(--unit_8) var(--unit_7);
}

.footer-sticky {
  position: sticky;
  bottom: 0;
  background: var(--background-primary);
  border-radius: 0 0 var(--unit_4) var(--unit_4);
}

.footer-divider {
  border-top: 0.5px solid var(--stroke-divider-default);
}

@media (max-width: 640px) {
  .footer {
    padding: var(--unit_3) var(--unit_4) var(--unit_4);
  }

  .footer-sticky {
    border-radius: 0;
  }
}

/* END Dialog Footer */

/* START CSS Animation */
@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

.overlay[data-state='open'],
.content[data-state='open'] {
  animation-name: fade-in;
  animation-duration: 200ms;
  animation-timing-function: ease-in;
}

.overlay[data-state='closed'],
.content[data-state='closed'] {
  animation-name: fade-out;
  animation-duration: 200ms;
  animation-timing-function: ease-out;
}

@keyframes slide-up {
  from {
    transform: translate3d(0, 100%, 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

@keyframes slide-down {
  from {
    transform: translate3d(0, var(--initial-translate, 0), 0);
  }

  to {
    transform: translateY(100%);
  }
}

@media (max-width: 640px) {
  .content[data-state='open'] {
    animation-name: fade-in, slide-up;
  }

  .content[data-state='closed'] {
    animation-name: fade-out, slide-down;
  }
}
/* END CSS Animation */
